using System;using System.Globalization;using UnityEngine;using UnityEngine.UI;using TMPro;using Unity.Properties;using UnityEngine.Rendering;public class Buttons : MonoBehaviour{    public Button[] ButtonsArray;    public TMP_InputField InputField;    public void Start()    {        foreach (var button in ButtonsArray)        {            button.onClick.AddListener(() => ButtonClick(button));        }    }    public void ButtonClick(Button button)    {        var textButton = button.GetComponentInChildren<TextMeshProUGUI>().text;        InputField.text = InputField.text + textButton; // вывод в окно число по кнопке        switch (button.name)        {            case "Button C":                InputField.text = string.Empty; //эта база, пустая строка                break;            case "Button =":                string result = GetCalculatedResult(InputField.text);                InputField.text = result;                break;            case "Button /":                TryPrecalculate('/');                break;            case "Button +":                TryPrecalculate('+');                break;            case "Button -":                TryPrecalculate('-');                break;            case "Button *":                TryPrecalculate('*');                break;        }    }    private void TryPrecalculate(char symbol)    {        int lastSymbolIndex = InputField.text.Length - 1;        bool hasSymbol = !int.TryParse(InputField.text.Remove(lastSymbolIndex), out var _); //проверка символа в строке ранее        if (hasSymbol)        {            string result = GetCalculatedResult(InputField.text);            InputField.text = result + symbol;        }    }    private string GetCalculatedResult(string value)    {        char[] array = value.ToCharArray();        string leftOperand = string.Empty; //пустая строка, цифры числа левый операнд        for (int i = 0; i < array.Length; i++)        {            bool isNumber = int.TryParse(array[i].ToString(), out var number);            if (isNumber)            {                leftOperand = leftOperand + array[i];            }            else            {                double leftNumber = double.Parse(leftOperand); //меняется только переменная                string rightOperand = value.Substring(i + 1, value.Length - i - 2); // длина с конца для правого операнда                double rightNumber = double.Parse(rightOperand); //меняется только переменная                double result = 0d;                switch (array[i])                {                    case '+':                        result = leftNumber + rightNumber;                        break;                    case '-':                        result = leftNumber - rightNumber;                        break;                    case '/':                        result = leftNumber / rightNumber;                        break;                    case '*':                        result = leftNumber * rightNumber;                        break;                }                value = result.ToString(CultureInfo.InvariantCulture);                return value;            }        }        return null;    }}